import { intrinsicSizeMeasureFunc } from '../tools/utils.ts'
import Yoga from 'yoga-layout';
import {
  Align,
  BoxSizing,
  Direction,
  Display,
  Edge,
  Errata,
  ExperimentalFeature,
  FlexDirection,
  GridTrackType,
  Gutter,
  Justify,
  MeasureMode,
  Overflow,
  PositionType,
  Unit,
  Wrap,
} from 'yoga-layout';

test('grid_aspect_ratio_child_fill_content_width', () => {
  const config = Yoga.Config.create();

  const root = Yoga.Node.create(config);
  root.setPositionType(PositionType.Absolute);
  root.setDisplay(Display.Grid);

  const root_child0 = Yoga.Node.create(config);
  root_child0.setAspectRatio(2);
  root.insertChild(root_child0, 0);
  root_child0.setMeasureFunc(intrinsicSizeMeasureFunc.bind({text: "HHHH", flexDirection: FlexDirection.Column}));

  const root_child1 = Yoga.Node.create(config);
  root_child1.setHeight(20);
  root.insertChild(root_child1, 1);
  root.calculateLayout(undefined, undefined, Direction.LTR);

  expect(root.getComputedLeft()).toBe(0);
  expect(root.getComputedTop()).toBe(0);
  expect(root.getComputedWidth()).toBe(40);
  expect(root.getComputedHeight()).toBe(40);

  expect(root_child0.getComputedLeft()).toBe(0);
  expect(root_child0.getComputedTop()).toBe(0);
  expect(root_child0.getComputedWidth()).toBe(40);
  expect(root_child0.getComputedHeight()).toBe(20);

  expect(root_child1.getComputedLeft()).toBe(0);
  expect(root_child1.getComputedTop()).toBe(20);
  expect(root_child1.getComputedWidth()).toBe(40);
  expect(root_child1.getComputedHeight()).toBe(20);

  root.calculateLayout(undefined, undefined, Direction.RTL);

  expect(root.getComputedLeft()).toBe(0);
  expect(root.getComputedTop()).toBe(0);
  expect(root.getComputedWidth()).toBe(40);
  expect(root.getComputedHeight()).toBe(40);

  expect(root_child0.getComputedLeft()).toBe(0);
  expect(root_child0.getComputedTop()).toBe(0);
  expect(root_child0.getComputedWidth()).toBe(40);
  expect(root_child0.getComputedHeight()).toBe(20);

  expect(root_child1.getComputedLeft()).toBe(0);
  expect(root_child1.getComputedTop()).toBe(20);
  expect(root_child1.getComputedWidth()).toBe(40);
  expect(root_child1.getComputedHeight()).toBe(20);
});
